/* @autogenerated */
package net.civeira.phylax.common.security;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.time.Duration;
import java.time.Instant;
import java.util.List;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.security.impl.ActorImpl;

@DisplayName("Actor default methods")
class ActorDefaultsUnitTest {

  private static final Actor ACTOR =
      ActorImpl.builder().uid("u-1").authenticated(true).roles(List.of("admin", "tenant:reader"))
          .groups(List.of("staff", "team:core")).scopes(List.of("read", "api:write")).build();

  @Nested
  @DisplayName("MFA")
  class Mfa {

    @Test
    @DisplayName("Should not report MFA for anonymous actors even if the flag is set")
    void shouldNotReportMfaForAnonymous() {
      Actor anonymous =
          ActorImpl.builder().authenticated(false).mfa(true).authenticatedAt(Instant.now()).build();
      assertFalse(anonymous.hasMfa());
      assertFalse(anonymous.hasMfa(Duration.ofMinutes(5)));
    }

    @Test
    @DisplayName("Should report recent MFA only within the allowed age")
    void shouldReportRecentMfa() {
      Actor actor = ActorImpl.builder().authenticated(true).mfa(true)
          .authenticatedAt(Instant.now().minus(Duration.ofMinutes(1))).build();
      assertTrue(actor.hasMfa(Duration.ofMinutes(5)));
      assertFalse(actor.hasMfa(Duration.ofSeconds(1)));
    }
  }

  @Nested
  @DisplayName("Identity")
  class Identity {

    @Test
    @DisplayName("Should compare the uid")
    void shouldCompareUid() {
      assertTrue(ACTOR.isIdentifiedAs("u-1"));
      assertFalse(ACTOR.isIdentifiedAs("u-2"));
    }
  }

  @Nested
  @DisplayName("Groups")
  class Groups {

    @Test
    @DisplayName("Should match exact and wildcard groups")
    void shouldMatchGroups() {
      assertTrue(ACTOR.isInGroup("staff"));
      assertFalse(ACTOR.isInGroup("guests"));
      assertTrue(ACTOR.isInGroup("team:*"));
      assertFalse(ACTOR.isInGroup("other:*"));
    }

    @Test
    @DisplayName("Should match any of several groups")
    void shouldMatchAnyGroup() {
      assertTrue(ACTOR.isInAnyGroup("guests", "staff"));
      assertFalse(ACTOR.isInAnyGroup("guests", "other:*"));
      assertFalse(ACTOR.isInAnyGroup());
    }
  }

  @Nested
  @DisplayName("Scopes")
  class Scopes {

    @Test
    @DisplayName("Should match exact and wildcard scopes")
    void shouldMatchScopes() {
      assertTrue(ACTOR.hasScope("read"));
      assertTrue(ACTOR.hasScope("api:*"));
      assertFalse(ACTOR.hasScope("other:*"));
    }

    @Test
    @DisplayName("Should match any of several scopes")
    void shouldMatchAnyScope() {
      assertTrue(ACTOR.hasAnyScope("write", "read"));
      assertFalse(ACTOR.hasAnyScope("write", "other:*"));
      assertFalse(ACTOR.hasAnyScope());
    }
  }

  @Nested
  @DisplayName("Roles")
  class Roles {

    @Test
    @DisplayName("Should match exact and wildcard roles")
    void shouldMatchRoles() {
      assertTrue(ACTOR.hasRole("admin"));
      assertTrue(ACTOR.hasRole("tenant:*"));
      assertFalse(ACTOR.hasRole("other:*"));
    }

    @Test
    @DisplayName("Should match any of several roles")
    void shouldMatchAnyRole() {
      assertTrue(ACTOR.hasAnyRole("guest", "admin"));
      assertFalse(ACTOR.hasAnyRole("guest", "other:*"));
      assertFalse(ACTOR.hasAnyRole());
    }
  }
}
